// Services/Export/WatermarkOverlay.swift

import SwiftUI

protocol WatermarkOverlay {
    func apply(to image: UIImage) -> UIImage?
}

struct DefaultWatermarkOverlay: WatermarkOverlay {

    private let watermarkImage: UIImage

    init() {
        if let image = UIImage(named: "freeTierWatermark") {
            self.watermarkImage = image
        } else {
            fatalError("Free tier watermark not found in assets")
        }
    }

    func apply(to image: UIImage) -> UIImage? {
        guard let cgImage = image.cgImage else { return nil }
        let contextSize = CGSize(width: cgImage.width, height: cgImage.height)
        UIGraphicsBeginImageContextWithOptions(contextSize, false, 1.0)

        // Draw the original image
        let context = UIGraphicsGetCurrentContext()!
        context.draw(cgImage, in: CGRect(origin: .zero, size: contextSize))

        // Calculate watermark position (e.g., bottom right corner with a margin)
        let watermarkSize = watermarkImage.size
        let x = contextSize.width - watermarkSize.width - 20
        let y = contextSize.height - watermarkSize.height - 20

        // Draw the watermark
        context.draw(watermarkImage.cgImage!, in: CGRect(x: x, y: y, width: watermarkSize.width, height: watermarkSize.height))

        // Get the resulting image with the watermark
        let watermarkedImage = UIGraphicsGetImageFromCurrentImageContext()
        UIGraphicsEndImageContext()

        return watermarkedImage
    }
}
```

