### Code:
Let's start by defining the protocol and basic structure:

```swift
// Services/Export/MetadataScrubber.swift

import UIKit

protocol MetadataScrubber {
    func scrub(from image: UIImage) -> UIImage?
}

struct DefaultMetadataScrubber: MetadataScrubber {

    func scrub(from image: UIImage) -> UIImage? {
        guard let sourceData = image.jpegData(compressionQuality: 1.0) else { return nil }

        // Create a CGImageSource from the original image data
        guard let source = CGImageSourceCreateWithData(sourceData as CFData, nil) else { return nil }

        // Specify properties to remove EXIF metadata
        let options: [CFString : Any] = [
            kCGImagePropertyExifDictionary as CFString : [:]
        ]

        // Create a new image destination
        guard let destinationData = NSMutableData() else { return nil }
        guard let destination = CGImageDestinationCreateWithData(destinationData, UTType.jpeg.identifier as CFString, 1, options as CFDictionary) else { return nil }

        // Copy the first (and only) image from the source to the destination
        CGImageDestinationAddImageFromSource(destination, source, 0, nil)

        // Finalize the destination
        guard CGImageDestinationFinalize(destination) else { return nil }

        // Create a UIImage from the new data with scrubbed metadata
        return UIImage(data: destinationData as Data)
    }
}
```

